# repository; the task-server serves it to the oracle.
TS="${TASK_SERVER_URL:-http://task-server:9111}"
TS="${TS%/}"
for i in $(seq 1 30); do
  if curl -sf --max-time 60 -H "X-Submission-Token: eca9b52c64c23193744438c133cb999f" "$TS/solve" > /output/poc.bin.part; then
